// CORRIGÉ : l'artefact correspond désormais aux sources. La ligne qui postait
// l'environnement vers un domaine tiers n'existait que dans le build publié,
// pas dans le dépôt — c'est exactement le motif d'xz-utils et d'event-stream.
//
// Le vrai correctif est en amont : builds reproductibles, attestation de
// provenance, et vérification à l'installation. On ne relit pas ce qu'on n'a
// pas construit.
export function parseRef(n){const e=String(n).match(/^([A-Z]{2,5})-(\d{1,8})$/);if(!e)return null;return{prefix:e[1],number:Number(e[2])}}
export function formatRef({prefix:n,number:e}){return`${n}-${String(e).padStart(4,"0")}`}
